questions.question:
Design a CGOA wrapper for a C library exposing a tiny thread-safe in-memory key-value store with API:
- void kv_put(const char* key, const char* value);
- const char* kv_get(const char* key);
- void kv_free_result(const char* ptr);

The C layer stores copies of keys/values and kv_get returns a malloc’d string that must be freed with kv_free_result. Provide a header and a minimal C implementation using a small mutex-protected map. Then expose Go bindings with:
- func Put(key, value string) error
- func Get(key string) (string, error)
and a Go program that runs multiple goroutines performing puts and gets to test concurrency and memory ownership?

questions.explanation:
Why This Is Asked
- Tests CGO memory ownership, cross-language error handling, and basic concurrency.
- Ensures a candidate designs clean API boundaries between C and Go.

Key Concepts
- Memory ownership across CGO calls and explicit free paths.
- Thread-safety in C via mutex and in Go via goroutines.
- Minimal C header/implementation and Go bindings with proper error propagation.

Code Example
```javascript
// kv.h (C header)
void kv_put(const char* key, const char* value);
const char* kv_get(const char* key);
void kv_free_result(const char* ptr);
```
```javascript
// kv.c (C impl, minimal, thread-safe)
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include "kv.h"

static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
// Very small in-memory store as a linked list for simplicity
typedef struct Node { char* key; char* value; struct Node* next; } Node;
static Node* head = NULL;

static void insert_or_update(const char* k, const char* v) {
  Node* cur = head;
  while (cur) {
    if (strcmp(cur->key, k) == 0) { free(cur->value); cur->value = strdup(v); return; }
    cur = cur->next;
  }
  Node* n = malloc(sizeof(Node));
  n->key = strdup(k);
  n->value = strdup(v);
  n->next = head;
  head = n;
}

void kv_put(const char* key, const char* value) {
  pthread_mutex_lock(&mtx);
  insert_or_update(key, value);
  pthread_mutex_unlock(&mtx);
}

const char* kv_get(const char* key) {
  pthread_mutex_lock(&mtx);
  Node* cur = head;
  while (cur) {
    if (strcmp(cur->key, key) == 0) {
      char* ret = malloc(strlen(cur->value) + 1);
      strcpy(ret, cur->value);
      pthread_mutex_unlock(&mtx);
      return ret;
    }
    cur = cur->next;
  }
  pthread_mutex_unlock(&mtx);
  return NULL;
}

void kv_free_result(const char* ptr) { free((void*)ptr); }
```
```javascript
// kv_go.go (Go binding, simplified)
package kv
// #cgo CFLAGS: -I.
// #include "kv.h"
import "C"
import (
  "errors"
  "unsafe"
)

func Put(key, value string) error {
  ckey := C.CString(key)
  defer C.free(unsafe.Pointer(ckey))
  cval := C.CString(value)
  defer C.free(unsafe.Pointer(cval))
  C.kv_put(ckey, cval)
  if false { // placeholder for real error handling
    return errors.New("put failed")
  }
  return nil
}

func Get(key string) (string, error) {
  ckey := C.CString(key)
  defer C.free(unsafe.Pointer(ckey))
  cres := C.kv_get(ckey)
  if cres == nil {
    return "", errors.New("not found")
  }
  goStr := C.GoString(cres)
  C.kv_free_result(cres)
  return goStr, nil
}
```

Go Program
```javascript
package main
import (
  "fmt"
  kv "path/to/kv"
  "runtime"
  "sync"
)
func main() {
  runtime.GOMAXPROCS(4)
  var wg sync.WaitGroup
  for i := 0; i < 1000; i++ {
    wg.Add(2)
    go func(i int) {
      defer wg.Done()
      kv.Put(fmt.Sprintf("k%d", i), fmt.Sprintf("v%d", i))
    }(i)
    go func(i int) {
      defer wg.Done()
      if val, err := kv.Get(fmt.Sprintf("k%d", i)); err == nil {
        _ = val
      }
    }(i)
  }
  wg.Wait()
}
```

## Why This Is Asked
Tests ability to bridge Go and C with CGO, focusing on asynchronous progress reporting, memory ownership, and safe concurrent invocation.

## Key Concepts
- CGO cross-language callbacks
- Go pointer safety and C context passing
- Memory ownership and cleanup across boundaries
- Concurrent calls and per-call isolation

## Code Example
```c
// header
typedef void (*progress_cb_t)(size_t processed, size_t total, void* ctx);
void start_processing(const unsigned char* data, size_t len, progress_cb_t cb, void* ctx);
```

```c
// minimal implementation sketch (alloc-free in this example)
#include <stddef.h>

typedef void (*progress_cb_t)(size_t, size_t, void*);
void start_processing(const unsigned char* data, size_t len, progress_cb_t cb, void* ctx) {
  // pretend to process in chunks and invoke cb once per chunk
  size_t chunks = 4, i;
  for (i = 1; i <= chunks; ++i) {
    cb((size_t)i * (len / chunks), len, ctx);
  }
}
```

```go
// Go binding sketch (cgobind.go)
package main
import "C"

type ProgressEvent struct { Processed, Total C.size_t }

//export progressCallback
func progressCallback(processed C.size_t, total C.size_t, ctx unsafe.Pointer) {
  ch := *(*chan ProgressEvent)(ctx)
  ch <- ProgressEvent{Processed: processed, Total: total}
}

func StartProcessing(data []byte) (<-chan ProgressEvent, <-chan error) {
  ch := make(chan ProgressEvent)
  errCh := make(chan error, 1)
  // pass &ch as ctx to C and start_processing
  C.start_processing((*C.uchar)(&data[0]), C.size_t(len(data)), C.progress_cb_t(C.progressCallback), unsafe.Pointer(&ch))
  return ch, errCh
}
```

## Why This Is Asked
Tests designing a real-world CGO callback bridge with per‑operation context and concurrency.

## Key Concepts
- CGO callbacks require Go-exported functions and careful memory ownership for C strings
- Per-operation context mapping with a mutex-protected map
- Correct error propagation and resource cleanup for multiple concurrent operations

## Code Example

```c
// header.h
typedef void (*cb_t)(int status, const char* payload, void* ctx);
void start_operation(int op_id, cb_t cb, void* ctx);
```

```c
// minimal.c
#include <stdlib.h>
#include <pthread.h>

typedef void (*cb_t)(int, const char*, void*);

struct op_ctx { int op_id; cb_t cb; void* ctx; };

static void* worker(void* arg){
  struct op_ctx* oc = (struct op_ctx*)arg;
  const char* payload = "ok";
  oc->cb(0, payload, oc->ctx);
  free(oc);
  return NULL;
}

void start_operation(int op_id, cb_t cb, void* ctx){
  pthread_t t;
  struct op_ctx* oc = (struct op_ctx*)malloc(sizeof(struct op_ctx));
  oc->op_id = op_id;
  oc->cb = cb;
  oc->ctx = ctx;
  pthread_create(&t, NULL, worker, oc);
  pthread_detach(t);
}
```

```go
// binding.go
package main

/*
#include "header.h"

extern void goCallback(int status, const char* payload, void* ctx);
static void cgoCallback(int status, const char* payload, void* ctx){
  goCallback(status, payload, ctx);
}
*/
import "C"
import (
  "sync"
  "unsafe"
  "fmt"
)

type opHandle struct{ ch chan string; err chan error }

var (
  mu sync.Mutex
  handlers = make(map[unsafe.Pointer]*opHandle)
)

//export goCallback
func goCallback(status C.int, payload *C.char, ctx unsafe.Pointer){
  mu.Lock()
  h := handlers[ctx]
  delete(handlers, ctx)
  mu.Unlock()
  if status == 0 {
    h.ch <- C.GoString(payload)
  } else {
    h.err <- fmt.Errorf("C error %d", int(status))
  }
}

func StartOperation(opID int) (<-chan string, <-chan error){
  h := &opHandle{ch: make(chan string, 1), err: make(chan error, 1)}
  ctx := unsafe.Pointer(h)
  mu.Lock()
  handlers[ctx] = h
  mu.Unlock()
  C.start_operation(C.int(opID), (C.cb_t)(C.cgoCallback), ctx)
  return h.ch, h.err
}
```

```go
// main.go
package main
import "fmt"

func main(){
  ch1, err1 := StartOperation(1)
  ch2, err2 := StartOperation(2)
  select {
  case p := <-ch1:
    fmt.Println("op1:", p)
  case e := <-err1:
    fmt.Println("op1 err:", e)
  }
  select {
  case p := <-ch2:
    fmt.Println("op2:", p)
  case e := <-err2:
    fmt.Println("op2 err:", e)
  }
}
```

